import {toast} from "react-toastify";
import React, {useState} from "react";
import {
    Alert,
    Button,
    Card,
    CardActions,
    CardContent,
    Chip,
    CircularProgress,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Grid,
    Stack,
    Typography,
} from "@mui/material";
import AddOutlinedIcon from "@mui/icons-material/AddOutlined";
import ArrowBackOutlinedIcon from "@mui/icons-material/ArrowBackOutlined";
import ContentCopyOutlinedIcon from "@mui/icons-material/ContentCopyOutlined";
import DeleteOutlineOutlinedIcon from "@mui/icons-material/DeleteOutlineOutlined";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import {useNavigate} from "react-router-dom";
import {
    CommercialOfferTemplate,
    formatOfferDate,
} from "../../models/commercialOffer";
import {
    EmptyState,
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
} from "../../ui/commonStyled/commonStyled";
import {
    useCreateCommercialOfferTemplateMutation,
    useDeleteCommercialOfferTemplateMutation,
    useGetCommercialOfferTemplatesQuery,
} from "./commercialOffersApi";

const CommercialOfferTemplatesPage = () => {
    const navigate = useNavigate();
    const {data: templates = [], isLoading, isError, refetch} = useGetCommercialOfferTemplatesQuery();
    const [createTemplate, {isLoading: cloning}] = useCreateCommercialOfferTemplateMutation();
    const [deleteTemplate, {isLoading: deleting}] = useDeleteCommercialOfferTemplateMutation();
    const [deleteCandidate, setDeleteCandidate] = useState<CommercialOfferTemplate | null>(null);
    const [error, setError] = useState("");

    const clone = async (template: CommercialOfferTemplate) => {
        setError("");
        try {
            const created = await createTemplate({
                name: `${template.name} — копия`,
                description: template.description,
                document: template.document,
            }).unwrap();
            toast.success("Копия шаблона создана.");
            navigate(`/commercialOffers/templates/${created.id}`);
        } catch {
            setError("Не удалось создать копию. Возможно, шаблон с таким названием уже существует.");
        }
    };

    const remove = async () => {
        if (!deleteCandidate) {
            return;
        }

        setError("");
        try {
            await deleteTemplate({
                id: deleteCandidate.id,
                concurrencyStamp: deleteCandidate.concurrencyStamp,
            }).unwrap();
            toast.success("Шаблон удалён.");
            setDeleteCandidate(null);
        } catch {
            setError("Не удалось удалить шаблон. Используемый в КП шаблон необходимо сначала заменить.");
            toast.error("Не удалось удалить шаблон. Используемый в КП шаблон необходимо сначала заменить.");
        }
    };

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <Button
                        startIcon={<ArrowBackOutlinedIcon/>}
                        onClick={() => navigate("/commercialOffers", {replace: true})}
                        sx={{alignSelf: "start", px: 0}}
                    >
                        К предложениям
                    </Button>
                    <PageTitle>Шаблоны коммерческих предложений</PageTitle>
                    <PageSubtitle>
                        Собирайте многостраничные A4-макеты: перетаскивайте блоки, задавайте координаты, тексты и изображения.
                    </PageSubtitle>
                </PageTitleGroup>
                <Button
                    variant="contained"
                    size="large"
                    startIcon={<AddOutlinedIcon/>}
                    onClick={() => navigate("/commercialOffers/templates/new")}
                >
                    Новый шаблон
                </Button>
            </PageHeader>

            {error && <Alert severity="error" sx={{mb: 2}} onClose={() => setError("")}>{error}</Alert>}
            {isError && (
                <Alert severity="error" action={<Button onClick={() => void refetch()}>Повторить</Button>}>
                    Не удалось получить шаблоны компании.
                </Alert>
            )}
            {isLoading && <CircularProgress/>}

            {!isLoading && !isError && templates.length === 0 && (
                <EmptyState>
                    <strong>Шаблонов пока нет</strong>
                    <span>Начните с готовой трёхстраничной композиции и адаптируйте её под фирменный стиль.</span>
                    <Button variant="contained" onClick={() => navigate("/commercialOffers/templates/new")}>
                        Создать первый шаблон
                    </Button>
                </EmptyState>
            )}

            <Grid container spacing={2}>
                {templates.map((template) => (
                    <Grid item xs={12} md={6} xl={4} key={template.id}>
                        <Card variant="outlined" sx={{height: "100%", display: "flex", flexDirection: "column"}}>
                            <CardContent sx={{flex: 1}}>
                                <Stack direction="row" justifyContent="space-between" gap={2} alignItems="start">
                                    <Typography variant="h6" fontWeight={800}>{template.name}</Typography>
                                    <Chip size="small" label={`${template.document.pageCount} стр.`}/>
                                </Stack>
                                <Typography color="text.secondary" sx={{mt: 1, minHeight: 48}}>
                                    {template.description || "Без описания"}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                    Обновлён {formatOfferDate(template.updatedAt)} · {template.document.elements.length} элементов
                                </Typography>
                            </CardContent>
                            <CardActions sx={{px: 2, pb: 2}}>
                                <Button
                                    startIcon={<EditOutlinedIcon/>}
                                    onClick={() => navigate(`/commercialOffers/templates/${template.id}`)}
                                >
                                    Редактировать
                                </Button>
                                <Button
                                    startIcon={<ContentCopyOutlinedIcon/>}
                                    onClick={() => void clone(template)}
                                    disabled={cloning}
                                >
                                    Копия
                                </Button>
                                <Button
                                    color="error"
                                    startIcon={<DeleteOutlineOutlinedIcon/>}
                                    onClick={() => setDeleteCandidate(template)}
                                    disabled={deleting}
                                >
                                    Удалить
                                </Button>
                            </CardActions>
                        </Card>
                    </Grid>
                ))}
            </Grid>

            <Dialog open={Boolean(deleteCandidate)} onClose={() => {if (!deleting) setDeleteCandidate(null);}}>
                <DialogTitle>Удалить шаблон?</DialogTitle>
                <DialogContent>
                    {error && <Alert severity="error" sx={{mb: 2}}>{error}</Alert>}
                    Шаблон «{deleteCandidate?.name}» будет удалён без возможности восстановления.
                </DialogContent>
                <DialogActions>
                    <Button disabled={deleting} onClick={() => setDeleteCandidate(null)}>Отмена</Button>
                    <Button color="error" variant="contained" onClick={() => void remove()} disabled={deleting}>
                        Удалить
                    </Button>
                </DialogActions>
            </Dialog>
        </MainDiv>
    );
};

export default CommercialOfferTemplatesPage;
